#!/usr/bin/env bash
# .env.local からビルド時に Secrets.swift を生成する。
# xcodegen の build phase から呼ばれ、gitignored なファイルとしてコミットせずに
# API key を Xcode のコンパイル時に見せる目的。
#
# 生成先: <project_root>/SameQ/Secrets.swift
# このファイルは .gitignore で除外済み（Secrets.swift）。
set -euo pipefail

# プロジェクトルート（scripts/ の1つ上）
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
ENV_FILE="$ROOT/.env.local"
OUT_FILE="$ROOT/SameQ/Secrets.swift"

if [[ ! -f "$ENV_FILE" ]]; then
  echo "[generate-secrets] .env.local not found at $ENV_FILE" >&2
  # フォールバック: ダミーキーを書いてビルドを通す（RevenueCat 経路は API 呼び出し時に失敗するだけ）
  cat > "$OUT_FILE" <<'EOF'
// AUTO-GENERATED by scripts/generate-secrets.sh. Do not edit by hand.
// .env.local が見つからないためダミーキーを出力。
import Foundation
enum Secrets {
    static let revenueCatAPIKey: String = ""
}
EOF
  exit 0
fi

# `KEY=VALUE` の行を VALUE 部分だけ取り出す（前後のクォートは剥がす）。
value_for() {
  local key="$1"
  local line
  line="$(grep -E "^${key}=" "$ENV_FILE" | head -n1 || true)"
  if [[ -z "$line" ]]; then
    echo ""
    return
  fi
  local value="${line#*=}"
  # 両端のクォートを剥がす
  value="${value%\"}"
  value="${value#\"}"
  value="${value%\'}"
  value="${value#\'}"
  printf '%s' "$value"
}

REVENUECAT_API_KEY="$(value_for REVENUECAT_API_KEY)"

# 1行コメントと `SwiftLint` 警告回避のため、ファイル末尾は改行で終える。
cat > "$OUT_FILE" <<EOF
// AUTO-GENERATED by scripts/generate-secrets.sh. Do not edit by hand.
// このファイルは .gitignore 対象（Secrets.swift）。
// .env.local から値を取り込み、ビルド時に Xcode へ見せる。
import Foundation

/// ビルド時に生成される秘密情報（RevenueCat の公開 API key など）。
/// RevenueCat の公開キーは iOS バイナリに埋め込み前提のため、この形式で取り込む。
enum Secrets {
    /// RevenueCat ダッシュボードで発行された公開 API key（appl_* 形式）。
    /// 未設定時は空文字。空文字のまま configure を呼ぶと SDK がエラー文字列を返す。
    static let revenueCatAPIKey: String = "${REVENUECAT_API_KEY}"
}
EOF
echo "[generate-secrets] wrote $OUT_FILE (revenueCatAPIKey=${REVENUECAT_API_KEY:0:8}...)"
